      "content": "{\n  \"name\": \"godot-bridge\",\n  \"version\": \"0.2.1\",\n  \"description\": \"DSH (DeepSeek Harness) plugin: launch and drive a running Godot 4.x game through its in-game TCP interaction server — replaces the godot-mcp MCP server with native agent tools.\",\n  \"type\": \"module\",\n  \"main\": \"plugin/godot-bridge.mjs\",\n  \"exports\": {\n    \".\": \"./plugin/godot-bridge.mjs\",\n    \"./client\": \"./client/client.js\"\n  },\n  \"files\": [\n    \"plugin/\",\n    \"client/\",\n    \"cordis.patch.yml\",\n    \"CHANGELOG.md\",\n    \"CHANGELOG.zh-CN.md\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"godot\",\n    \"godot-engine\",\n    \"godot-plugin\",\n    \"mcp\",\n    \"game-development\",\n    \"ai-agent\"\n  ],\n  \"scripts\": {\n    \"check\": \"node scripts/check-plugin-contract.mjs\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-tools\": \">=0.1.6-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Smalldy/godot-bridge.git\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\"\n      ]\n    }\n  }\n}\n"
