      await ctx.timeout(250)\n    }\n    if (trapText === '') return null\n    const trace = parseDebuggerTrace(trapText)\n    const wroteQuit = writeStdinTo(handle, plan.input)\n    const exited = await Promise.race([\n      Promise.resolve(handle.waitForExit(exec.signal)).then(function () { return true }).catch(function () { return true }),\n      ctx.timeout(plan.waitMs).then(function () { return false }),\n    ])\n    if (exited !== true) {\n      try { handle.terminate() } catch (e) {}\n      try { await handle.waitForExit(exec.signal) } catch (e) {}\n    }\n    return {\n      trace: trace,\n      wroteQuit: wroteQuit,\n      quitInput: plan.input,\n      exited: exited === true,\n      killed: exited !== true,\n      exitCode: exitCodeOf(handle),\n    }\n  }\n\n  /**\n   * Describe a managed instance that is sitting in the local debugger. Called\n   * when a command times out, so a debugger trap reads as one instead of a bare\n   * \"bridge timeout\". Best effort: writes quit and stops our own instance, keeps\n   * the parsed trace.\n   */\n  function debuggerTrapResult(command) {\n    if (!godot || godot.external || !godot.handle) return null\n    let text = ''\n    try {\n      if (godot.handle.collected && godot.handle.collected.stdout) text = godot.handle.collected.stdout.readFrom(0).text || ''\n    } catch (e) {\n      return null\n    }\n    if (text === '' || !detectDebuggerTrap(text)) return null\n    const plan = debuggerRecoveryPlan()\n    const wroteQuit = writeStdinTo(godot.handle, plan.input)\n    try { godot.handle.terminate() } catch (e) {}\n    return {\n      error: 'bridge timeout',\n      diagnosis: 'debugger-trap',\n      command: String(command),\n      debuggerTrace: parseDebuggerTrace(text),\n      quit_written: wroteQuit,\n      next: 'The instance entered the local debugger (a script error) and was stopped; the stack is in debuggerTrace. Restart without debug:true, or run code with godot_run_headless --script.',\n    }\n  }\n\n  /** Best-effort user:// log size warning; never deletes anything. */\n  async function userLogWarning(projectPath) {\n    try {\n      if (!ctx.fs || typeof ctx.fs.stat !== 'function') return null\n      const appData = process.env.APPDATA\n      if (!appData) return null\n      const name = String(projectPath).split(/[\\\\/]/).filter(Boolean).slice(-1)[0]\n      const path = join(appData, 'Godot', 'app_userdata', name, 'logs', 'godot.log')\n      const info = await ctx.fs.stat(path)\n      if (!info || typeof info.size !== 'number') return null\n      return logSizeWarning(info.size)\n    } catch (e) {\n      return null\n    }\n  }\n\n  // Spawn one Godot process on a concrete port (managed, owned by us).\n  async function spawnOwnInstance(gp, projectPath, port, opts, exec, extra) {\n    const token = newToken()\n    const debugMode = opts.debug === true\n    const argv = buildLaunchArgv(gp, projectPath, { debug: debugMode, scene: opts.scene })\n    let handle\n    try {\n      handle = subprocess.spawn({\n        argv: argv,\n        cwd: projectPath,\n        env: {\n          GODOT_BRIDGE_PORT: String(port),\n          GODOT_BRIDGE_TOKEN: token,\n          ...launchEnv(opts.debug === true),\n        },\n        stdio: {\n          // Diagnostic mode keeps a stdin pipe so the watchdog can write \"quit\";\n          // the default instance has no debugger and needs no stdin at all.\n          stdin: debugMode ? 'pipe' : 'ignore',\n          stdout: { collect: { maxBytes: 4 * 1024 * 1024, spill: { maxBytes: 32 * 1024 * 1024 } } },\n          stderr: { collect: { maxBytes: 4 * 1024 * 1024, spill: { maxBytes: 32 * 1024 * 1024 } } },\n        },\n        graceMs: 3000,\n        signal: exec.signal,\n      })\n    } catch (e) {\n      return { error: 'failed to spawn Godot: ' + (e && e.message) }\n    }\n    godot = {\n      handle: handle,\n      outOffset: 0,\n      errOffset: 0,\n      projectPath: projectPath,\n      scene: opts.scene || null,\n      port: port,\n      token: token,\n      external: false,\n      externalPid: null,\n    }\n    const ready = await waitForGame(exec.signal, opts.wait_ms || 20000, port)\n    let debuggerWatch = null\n    if (debugMode) debuggerWatch = await watchForDebugger(handle, exec, opts.wait_ms || 20000)\n    let diagnosis = null\n    if (!ready && debuggerWatch === null) {\n      let out = ''\n      let err = ''\n      try {\n        if (handle.collected && handle.collected.stdout) out = handle.collected.stdout.readFrom(0).text || ''\n        if (handle.collected && handle.collected.stderr) err = handle.collected.stderr.readFrom(0).text || ''\n      } catch (e) {}\n      diagnosis = diagnoseCrash(out, err)\n    }\n    const debugNote = debuggerNote(debugMode)\n    const logWarning = debugMode ? await userLogWarning(projectPath) : null\n    let scriptErrorText = ''\n    try {\n      if (handle.collected && handle.collected.stdout) scriptErrorText += handle.collected.stdout.readFrom(0).text || ''\n      if (handle.collected && handle.collected.stderr) scriptErrorText += handle.collected.stderr.readFrom(0).text || ''\n    } catch (e) {}\n    const scriptErrorHint = /SCRIPT ERROR/.test(scriptErrorText)\n      ? 'A SCRIPT ERROR was captured: read it here first (file and line are included). Only if you need the multi-frame stack, restart with debug:true (diagnostic mode: eval is disabled, and the run ends with a debuggerTrace).'\n      : null\n    const watchResult = debuggerWatch === null\n      ? null\n      : (function () {\n          const classified = classifyDebuggerExit({ exited: debuggerWatch.exited, exitCode: debuggerWatch.exitCode, killed: debuggerWatch.killed })\n          return {\n            diagnosis: classified.diagnosis,\n            exitCode: classified.exitCode,\n            crash: classified.crash,\n            killed: classified.killed,\n            debuggerTrace: debuggerWatch.trace,\n            next:\n              classified.diagnosis === 'debugger-quit'\n                ? 'The local debugger exited cleanly (exit 0). The script error is in debuggerTrace; fix it and restart without debug:true, or run code with godot_run_headless --script.'\n                : 'The instance did not exit cleanly after quit (exit ' + String(classified.exitCode) + (classified.crash ? ', access violation / crash' : ', killed') + '). The script error is in debuggerTrace; fix it and restart without debug:true, and run code with godot_run_headless --script because eval is disabled in diagnostic mode.',\n            debugger: { quit_written: debuggerWatch.wroteQuit, input: debuggerWatch.quitInput, killed: classified.killed },\n          }\n        })()\n    return {\n      pid: handle.pid,\n      project_path: projectPath,\n      godot_path: gp,\n      scene: opts.scene || null,\n      autoload: opts.autoload,\n      game_ready: ready && debuggerWatch === null,\n      managed: true,\n      external: false,\n      port: port,\n      debug: debugMode,\n      ...(scriptErrorHint ? { hint: scriptErrorHint } : {}),\n      ...(debugNote ? debugNote : {}),\n      ...(logWarning ? { log_warning: logWarning } : {}),\n      ...(extra.conflictNote ? { conflict: extra.conflictNote } : {}),\n      ...(diagnosis || {}),\n      ...(watchResult || {}),\n      note: ready && debuggerWatch === null\n        ? 'Game interaction server reachable on 127.0.0.1:' + port\n        : watchResult !== null\n          ? 'The instance entered the local debugger (diagnostic mode); it was stopped and the trace is in debuggerTrace.'\n          : (diagnosis\n            ? diagnosis.hint\n            : 'Game process started but the interaction server did not answer in time; call godot_get_debug_output to diagnose'),\n    }\n  }\n\n  // Common pre-flight for the runtime tools (godot_command / godot_screenshot):\n  // ensures a game is answering on 9090 before the call proceeds. When nothing\n  // is running it self-heals by starting the project IF a Godot project is\n  // derivable (explicit project_path, or the session workspace holding\n  // project.godot) — otherwise it returns actionable guidance instead of a\n  // bare ECONNREFUSED. Read-only probing, no cross-session side effects.\n  async function ensureGameService(args, exec) {\n    try {\n      const resp = await runGameCommand('get_performance', {}, 1500, exec.signal)\n      if (resp && !resp.error) return null\n    } catch (e) {}\n    // The plugin owns a process: give it boot grace, then diagnose.\n    if (godot) {\n      for (let i = 0; i < 5; i++) {\n        await ctx.timeout(1000)\n        if (exec.signal && exec.signal.aborted) return { error: 'cancelled while waiting for the game server' }\n        try {\n          const r = await runGameCommand('get_performance', {}, 1500, exec.signal)\n          if (r && !r.error) return null\n        } catch (e) {}\n      }\n      return { error: 'The Godot process is running but the interaction server (127.0.0.1:' + (godot.port || PORT) + ') is not answering; it may have crashed or the McpInteractionServer autoload is missing. Call godot_get_debug_output to diagnose, or godot_run_project to restart (it auto-installs the autoload).' }\n    }\n    // No game: derive a Godot project and self-heal by starting it.\n    let project = args.project_path || null\n    if (!project) {\n      const root = await getWorkspaceRoot(exec)\n      if (root) {\n        const pg = await readProjectFile(root, 'project.godot')\n        if (pg !== null) project = root\n      }\n    }\n    if (!project) {\n      return { error: 'No Godot game is answering on 127.0.0.1:' + PORT + ' and no Godot project is derivable here. Call godot_run_project with the project path to start it (it auto-installs the McpInteractionServer autoload), or pass project_path to this tool.' }\n    }\n    const autoload = await ensureInteractionAutoload(project)\n    if (autoload.status === 'error') return { error: 'autoload setup failed: ' + autoload.reason }\n    const launched = await launchProject(project, { autoload: autoload }, exec)\n    if (launched.error) return launched\n    if (!launched.game_ready) {\n      return { error: 'Started the game but the interaction server did not answer in time; call godot_get_debug_output to diagnose.' }\n    }\n    return null\n  }\n\n  // Extract one `[section]` block (up to the next `[section]` or EOF).\n  function getSection(content, section) {\n    const re = new RegExp('\\\\[' + section.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '\\\\]([\\\\s\\\\S]*?)(?=\\\\n\\\\[|$)')\n    const m = content.match(re)\n    return m ? m[1] : null\n  }\n\n  // Set `key=value` inside a section; creates the section when missing.\n  function setSectionKey(content, section, key, value) {\n    const header = '[' + section + ']'\n    const keyLine = key + '=' + value\n    const idx = content.indexOf(header)\n    if (idx === -1) return content.replace(/\\s*$/, '') + '\\n\\n' + header + '\\n\\n' + keyLine + '\\n'\n    const sectionEndRel = content.indexOf('\\n[', idx + header.length)\n    const sectionEnd = sectionEndRel === -1 ? content.length : sectionEndRel\n    const block = content.slice(idx, sectionEnd)\n    const keyRe = new RegExp('^' + key.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '\\\\s*=.*$', 'm')\n    let newBlock\n    if (keyRe.test(block)) newBlock = block.replace(keyRe, keyLine)\n    else newBlock = block.replace(/\\s*$/, '') + '\\n' + keyLine\n    return content.slice(0, idx) + newBlock + content.slice(sectionEnd)\n  }\n\n  // Remove `key=` lines inside a section.\n  function removeSectionKey(content, section, key) {\n    const header = '[' + section + ']'\n    const idx = content.indexOf(header)\n    if (idx === -1) return content\n    const sectionEndRel = content.indexOf('\\n[', idx + header.length)\n    const sectionEnd = sectionEndRel === -1 ? content.length : sectionEndRel\n    const block = content.slice(idx, sectionEnd)\n    const keyRe = new RegExp('\\\\n?' + key.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '\\\\s*